//! The file dictionary (R27, L091): `formats::file_table`, generated by `ecosystem/tools/build.py` from
//! `ecosystem/data/files.yml`, against the core.
//! - the table holds the YAML's kinds in its order (build.py was run), every field filled;
//! - every pattern uses only the known placeholders, and a name filled from a pattern is recognised as its kind
//!   (`files::path`, `files::kind_of`);
//! - the files the core writes follow it: the `.pcr` export of FullProf runs with a resolution file, a background
//!   file and a reflection list, and its processed data, are named as the dictionary's FullProf kinds say; a control
//!   file and a background file written by the core are named by `project::describe` with the dictionary's role.

use drs::formats::files::{self, FILES, PLACEHOLDERS};
use drs::formats::{project, Probe};
use std::path::Path;

fn root() -> &'static Path {
    Path::new(concat!(env!("CARGO_MANIFEST_DIR"), "/.."))
}

#[test]
fn file_dictionary() {
    let yml = std::fs::read_to_string(root().join("ecosystem/data/files.yml")).unwrap();
    let ids: Vec<&str> = yml.lines().filter_map(|l| l.strip_prefix("  - id: ")).map(str::trim).collect();
    assert_eq!(ids, FILES.iter().map(|k| k.id).collect::<Vec<_>>(), "file_table is not the YAML's (run build.py)");
    let mut fails = Vec::new();
    for k in FILES {
        for (field, v) in [("name", k.name), ("pattern", k.pattern), ("extension", k.extension), ("role", k.role), ("contents", k.contents), ("format", k.format), ("fullprof", k.fullprof), ("gsas2", k.gsas2), ("written_by", k.written_by), ("status", k.status), ("reason", k.reason)] {
            if v.trim().is_empty() {
                fails.push(format!("{}: {field} is empty", k.id));
            }
        }
        if !["control", "data", "input", "output", "version", "state"].contains(&k.role) {
            fails.push(format!("{}: role {}", k.id, k.role));
        }
        if !(k.status.starts_with("decided") || k.status.starts_with("proposed")) {
            fails.push(format!("{}: status {}", k.id, k.status));
        }
        for p in files::placeholders(k.pattern) {
            if !PLACEHOLDERS.contains(&p) {
                fails.push(format!("{}: {{{p}}} is not a known placeholder", k.id));
            }
        }
        // A name filled from the pattern is recognised as this kind (for a fixed extension, it ends in it).
        let values: Vec<(&str, &str)> = PLACEHOLDERS.iter().map(|&p| (p, match p { "time" => "2026-10-11 09.30.00", "n" => "2", _ => "Sr2ScSbO6 RT" })).collect();
        let path = files::path(k.id, &values).unwrap();
        match files::kind_of(&path) {
            Some(found) if found.id == k.id => {}
            other => fails.push(format!("{}: {path} is recognised as {:?}", k.id, other.map(|f| f.id))),
        }
        // A fixed extension ("any" or a phrase for the kinds that keep a file's own name or await R28).
        let fixed = k.extension != "any" && k.extension.chars().all(|c| c.is_ascii_alphanumeric());
        if fixed && !path.ends_with(&format!(".{}", k.extension)) {
            fails.push(format!("{}: {path} does not end in .{}", k.id, k.extension));
        }
    }
    println!("{} kinds: {} decided, {} proposed", FILES.len(), FILES.iter().filter(|k| k.status.starts_with("decided")).count(), FILES.iter().filter(|k| k.status.starts_with("proposed")).count());
    assert!(fails.is_empty(), "{}", fails.join("\n"));
}

#[test]
fn the_core_writes_the_dictionarys_names() {
    let mut fails = Vec::new();
    let mut seen = std::collections::BTreeSet::new();
    // FullProf runs whose export writes the other files: a resolution file (Egypt, Res = 1), a reflection list (profile
    // matching, Co-YBCO-LeBail), a background file (a control file keeping its points in a .bac).
    let runs = root().join("manuals/fullprof/runs");
    for (run, pcr) in [("Egypt", "Egypt_qa_Rietveld.pcr"), ("Co-YBCO-LeBail", "Cocuc_LeBail_conv.pcr"), ("Y2O3", "y2o3_structure.pcr")] {
        let dir = runs.join(run);
        let Ok(text) = std::fs::read(dir.join(pcr)) else { panic!("{run}/{pcr}") };
        let text: String = text.iter().map(|&b| b as char).collect();
        let p = drs::pcr::read(&text).unwrap();
        let stem = pcr.trim_end_matches(".pcr");
        let mut c = drs::control::Control::from_pcr(&p, &dir, stem, &dir).unwrap();
        if run == "Y2O3" {
            // The points kept in a .bac and fixed (FullProf refines a .bac's scale, not its values: L082), and a data
            // operation, so that the data are written processed.
            c.background_file = Some(format!("{stem}.bac"));
            c.refinement.parameters.retain(|terms| !terms.iter().any(|(f, _)| matches!(f, drs::jacobian::Field::Background(_))));
            if let Some(d) = c.data.as_mut() {
                d.operations.push(drs::data_ops::Operation::Mask { from: 140.0, to: 145.0 });
            }
        }
        let data = drs::powder::Model::from_pcr(&p, &dir, stem).ok().and_then(|l| l.data);
        let e = drs::control::pcr_export::export(&c, stem, data.as_ref()).unwrap_or_else(|e| panic!("{run}: {e}"));
        println!("{run}: the export writes {stem}.pcr and {:?}", e.files.iter().map(|f| &f.0).collect::<Vec<_>>());
        for name in std::iter::once(format!("{stem}.pcr")).chain(e.files.iter().map(|(n, _)| n.clone())) {
            match files::kind_of(&format!("Exports/FullProf/{name}")) {
                Some(k) if k.id.starts_with("fullprof_") && files::path(k.id, &[("control", stem), ("n", "1")]).is_ok() => {
                    seen.insert(k.id);
                }
                other => fails.push(format!("{run}: the export writes {name}, which is {:?} in the dictionary", other.map(|k| k.id))),
            }
        }
        // The control file the core writes is named, by its content, a control file.
        let ctl = files::path("control", &[("project", stem)]).unwrap();
        let text = c.to_text();
        match project::describe(&Probe::new(&ctl, text.as_bytes())) {
            project::Description::Project(k) if k.role == project::Role::Control => {}
            other => fails.push(format!("{ctl}: described as {other:?}")),
        }
    }
    // A background file the core writes, named as the dictionary says.
    let drb = files::path("background_points", &[("stem", "y2o3_structure")]).unwrap();
    let text = drs::background::write_ours(&[(10.0, 100.0), (50.0, 120.0)], drs::background::Interpolation::Linear);
    match project::describe(&Probe::new(&drb, text.as_bytes())) {
        project::Description::Project(k) if k.role == project::Role::Input => {}
        other => fails.push(format!("{drb}: described as {other:?}")),
    }
    println!("the export's files: {seen:?}; {drb} described as background points");
    for id in ["fullprof_pcr_export", "fullprof_resolution_export", "fullprof_reflections_export", "fullprof_data_export", "fullprof_background_export"] {
        if !seen.contains(id) {
            fails.push(format!("no export wrote a file of kind {id}"));
        }
    }
    assert!(fails.is_empty(), "{}", fails.join("\n"));
}

/// The app's request 37: Publish's set file, `Publish/{name}.drp`, named by the dictionary, and known by its format line
/// wherever it lies (as a plot set, PL24).
#[test]
fn publication_set() {
    assert_eq!(files::path("publication_set", &[("name", "thesis chapter 4")]).unwrap(), "Publish/thesis chapter 4.drp");
    assert_eq!(files::kind_of("Publish/thesis chapter 4.drp").map(|k| k.id), Some("publication_set"));
    let text = "format = \"drs-publish set 1\"\ntitle = \"Sr2ScSbO6 at 300 K\"\n";
    for path in ["Publish/thesis.drp", "elsewhere/any name.txt"] {
        match project::describe(&Probe::new(path, text.as_bytes())) {
            project::Description::Project(k) if k.id == "publication_set" && k.role == project::Role::Input => {}
            other => panic!("{path}: described as {other:?}"),
        }
    }
}
